  1→package kiro
  2→
  3→import (
  4→	"context"
  5→	"crypto/rand"
  6→	"encoding/hex"
  7→	"errors"
  8→	"io"
  9→	"os"
 10→	"path/filepath"
 11→	"strings"
 12→	"time"
 13→
 14→	"github.com/entireio/cli/cmd/entire/cli/agent"
 15→	"github.com/entireio/cli/cmd/entire/cli/logging"
 16→	"github.com/entireio/cli/cmd/entire/cli/paths"
 17→)
 18→
 19→// Compile-time interface assertion for TranscriptAnalyzer.
 20→var _ agent.TranscriptAnalyzer = (*KiroAgent)(nil)
 21→
 22→// Kiro hook names — these become CLI subcommands under `entire hooks kiro`.
 23→// Kiro uses camelCase hook names natively, but CLI subcommands use kebab-case.
 24→const (
 25→	HookNameAgentSpawn       = "agent-spawn"
 26→	HookNameUserPromptSubmit = "user-prompt-submit"
 27→	HookNamePreToolUse       = "pre-tool-use"
 28→	HookNamePostToolUse      = "post-tool-use"
 29→	HookNameStop             = "stop"
 30→)
 31→
 32→// sessionIDFile is the filename for caching the generated session ID.
 33→// Stored in .entire/tmp/ to ensure a stable ID across all hooks in one session.
 34→const sessionIDFile = "kiro-active-session"
 35→
 36→// HookNames returns the hook verbs Kiro supports.
 37→// These become subcommands: entire hooks kiro <verb>
 38→func (k *KiroAgent) HookNames() []string {
 39→	return []string{
 40→		HookNameAgentSpawn,
 41→		HookNameUserPromptSubmit,
 42→		HookNamePreToolUse,
 43→		HookNamePostToolUse,
 44→		HookNameStop,
 45→	}
 46→}
 47→
 48→// ParseHookEvent translates a Kiro hook into a normalized lifecycle Event.
 49→// Returns nil for hooks with no lifecycle significance (preToolUse, postToolUse).
 50→func (k *KiroAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
 51→	switch hookName {
 52→	case HookNameAgentSpawn:
 53→		return k.parseAgentSpawn(ctx, stdin)
 54→	case HookNameUserPromptSubmit:
 55→		return k.parseUserPromptSubmit(ctx, stdin)
 56→	case HookNameStop:
 57→		return k.parseStop(ctx, stdin)
 58→	case HookNamePreToolUse, HookNamePostToolUse:
 59→		// Pass-through hooks with no lifecycle significance
 60→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
 61→	default:
 62→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 63→	}
 64→}
 65→
 66→// readHookInputOrEmpty wraps ReadAndParseHookInput, returning a zero-value
 67→// hookInputRaw on empty stdin instead of erroring. This supports the Kiro IDE
 68→// which delivers data via environment variables rather than JSON on stdin.
 69→// Malformed JSON still returns an error.
 70→func readHookInputOrEmpty(stdin io.Reader) (*hookInputRaw, error) {
 71→	raw, err := agent.ReadAndParseHookInput[hookInputRaw](stdin)
 72→	if err != nil {
 73→		if errors.Is(err, agent.ErrEmptyHookInput) {
 74→			return &hookInputRaw{}, nil
 75→		}
 76→		return nil, err
 77→	}
 78→	return raw, nil
 79→}
 80→
 81→func (k *KiroAgent) parseAgentSpawn(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
 82→	_, err := readHookInputOrEmpty(stdin)
 83→	if err != nil {
 84→		return nil, err
 85→	}
 86→
 87→	// Generate a new stable session ID and cache it for subsequent hooks.
 88→	// Kiro's SQLite transcript isn't populated until the turn ends, so we can't
 89→	// use the native conversation_id as our session ID — it would be "unknown"
 90→	// at agentSpawn/userPromptSubmit and change to the real ID at stop.
 91→	sessionID := k.generateAndCacheSessionID(ctx)
 92→
 93→	return &agent.Event{
 94→		Type:      agent.SessionStart,
 95→		SessionID: sessionID,
 96→		Timestamp: time.Now(),
 97→	}, nil
 98→}
 99→
100→func (k *KiroAgent) parseUserPromptSubmit(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
101→	raw, err := readHookInputOrEmpty(stdin)
102→	if err != nil {
103→		return nil, err
104→	}
105→
106→	// IDE mode: prompt comes from USER_PROMPT env var when stdin is empty.
107→	prompt := raw.Prompt
108→	if prompt == "" {
109→		prompt = os.Getenv("USER_PROMPT")
110→	}
111→
112→	// Read the stable session ID generated at agentSpawn.
113→	sessionID := k.readCachedSessionID(ctx)
114→	if sessionID == "" {
115→		// Fallback: generate new ID if cache file is missing (e.g., agentSpawn was skipped).
116→		sessionID = k.generateAndCacheSessionID(ctx)
117→	}
118→
119→	return &agent.Event{
120→		Type:      agent.TurnStart,
121→		SessionID: sessionID,
122→		Prompt:    prompt,
123→		Timestamp: time.Now(),
124→	}, nil
125→}
126→
127→func (k *KiroAgent) parseStop(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
128→	raw, err := readHookInputOrEmpty(stdin)
129→	if err != nil {
130→		return nil, err
131→	}
132→
133→	// IDE mode: CWD may not be in stdin. Fall back to repo root.
134→	cwd := raw.CWD
135→	if cwd == "" {
136→		repoRoot, rootErr := paths.WorktreeRoot(ctx)
137→		if rootErr == nil {
138→			cwd = repoRoot
139→		}
140→	}
141→
142→	// Read the stable session ID generated at agentSpawn.
143→	sessionID := k.readCachedSessionID(ctx)
144→	if sessionID == "" {
145→		// Fallback: try SQLite for the session ID.
146→		sid, queryErr := k.querySessionID(ctx, cwd)
147→		if queryErr != nil || sid == "" {
148→			sessionID = "unknown"
149→		} else {
150→			sessionID = sid
151→		}
152→	}
153→
154→	// At stop, Kiro's SQLite transcript is available. Fetch and cache it
155→	// under our stable session ID so lifecycle.go can read it.
156→	sessionRef, _ := k.ensureCachedTranscript(ctx, cwd, sessionID) //nolint:errcheck // best-effort: fall back to IDE or placeholder
157→
158→	// IDE mode: SQLite may not exist. Try the IDE's workspace session files.
159→	if sessionRef == "" {
160→		sessionRef, _ = k.ensureIDETranscript(ctx, cwd, sessionID) //nolint:errcheck // best-effort: fall back to placeholder
161→	}
162→
163→	// Last resort: create a minimal placeholder so the lifecycle handler can
164→	// proceed (file-diff checkpoints still work without a real transcript).
165→	if sessionRef == "" {
166→		sessionRef = k.createPlaceholderTranscript(ctx, cwd, sessionID)
167→	}
168→
169→	return &agent.Event{
170→		Type:       agent.TurnEnd,
171→		SessionID:  sessionID,
172→		SessionRef: sessionRef,
173→		Timestamp:  time.Now(),
174→	}, nil
175→}
176→
177→// createPlaceholderTranscript writes a minimal JSON transcript to .entire/tmp/
178→// so the lifecycle handler can proceed when the real transcript is unavailable
179→// (e.g., Kiro IDE mode where SQLite is at a different path).
180→func (k *KiroAgent) createPlaceholderTranscript(ctx context.Context, cwd, sessionID string) string {
181→	repoRoot, err := paths.WorktreeRoot(ctx)
182→	if err != nil {
183→		repoRoot = cwd
184→	}
185→	if repoRoot == "" {
186→		return ""
187→	}
188→	cacheDir := filepath.Join(repoRoot, ".entire", "tmp")
189→	cachePath := filepath.Join(cacheDir, sessionID+".json")
190→	if err := os.MkdirAll(cacheDir, 0o750); err != nil {
191→		logging.Warn(ctx, "kiro: failed to create transcript cache dir", "err", err)
192→		return ""
193→	}
194→	if err := os.WriteFile(cachePath, []byte("{}"), 0o600); err != nil {
195→		logging.Warn(ctx, "kiro: failed to write placeholder transcript", "err", err)
196→		return ""
197→	}
198→	return cachePath
199→}
200→
201→// generateAndCacheSessionID creates a new random session ID and writes it
202→// to .entire/tmp/kiro-active-session for subsequent hooks to read.
203→func (k *KiroAgent) generateAndCacheSessionID(ctx context.Context) string {
204→	sid := generateSessionID()
205→	cachePath := k.sessionIDCachePath(ctx)
206→	if err := os.MkdirAll(filepath.Dir(cachePath), 0o750); err != nil {
207→		logging.Warn(ctx, "kiro: failed to create session ID cache dir", "err", err)
208→		return sid
209→	}
210→	if err := os.WriteFile(cachePath, []byte(sid), 0o600); err != nil {
211→		logging.Warn(ctx, "kiro: failed to write session ID cache", "err", err)
212→	}
213→	return sid
214→}
215→
216→// readCachedSessionID reads the stable session ID from .entire/tmp/kiro-active-session.
217→// Returns empty string if the cache file doesn't exist.
218→func (k *KiroAgent) readCachedSessionID(ctx context.Context) string {
219→	cachePath := k.sessionIDCachePath(ctx)
220→	data, err := os.ReadFile(cachePath) //nolint:gosec // cachePath is constructed from WorktreeRoot + constant suffix
221→	if err != nil {
222→		return ""
223→	}
224→	return strings.TrimSpace(string(data))
225→}
226→
227→// sessionIDCachePath returns the path to the session ID cache file.
228→func (k *KiroAgent) sessionIDCachePath(ctx context.Context) string {
229→	repoRoot, err := paths.WorktreeRoot(ctx)
230→	if err != nil {
231→		repoRoot = "."
232→	}
233→	return filepath.Join(repoRoot, ".entire", "tmp", sessionIDFile)
234→}
235→
236→// generateSessionID creates a random 32-character hex string for use as a session ID.
237→func generateSessionID() string {
238→	b := make([]byte, 16)
239→	if _, err := rand.Read(b); err != nil {
240→		// crypto/rand.Read never fails on supported platforms, but use timestamp fallback.
241→		return "kiro-" + time.Now().Format("20060102-150405")
242→	}
243→	return hex.EncodeToString(b)
244→}
