  1→package kiro
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"fmt"
  7→	"os"
  8→	"path/filepath"
  9→	"strings"
 10→
 11→	"github.com/entireio/cli/cmd/entire/cli/agent"
 12→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 13→	"github.com/entireio/cli/cmd/entire/cli/paths"
 14→)
 15→
 16→// Ensure KiroAgent implements HookSupport
 17→var _ agent.HookSupport = (*KiroAgent)(nil)
 18→
 19→// HooksFileName is the config file for Kiro hooks.
 20→const HooksFileName = "entire.json"
 21→
 22→// hooksDir is the directory within .kiro where agent hook configs live.
 23→const hooksDir = "agents"
 24→
 25→// ideHooksDir is the directory within .kiro where IDE hook files live.
 26→const ideHooksDir = "hooks"
 27→
 28→// ideHookFileSuffix is the file extension for IDE hook files.
 29→const ideHookFileSuffix = ".kiro.hook"
 30→
 31→// ideHookVersion is the schema version for IDE hook files.
 32→const ideHookVersion = "1"
 33→
 34→// vscodeSettingsDir is the directory for VS Code settings.
 35→const vscodeSettingsDir = ".vscode"
 36→
 37→// vscodeSettingsFile is the settings file within .vscode.
 38→const vscodeSettingsFile = "settings.json"
 39→
 40→// trustedCommandsKey is the VS Code settings key for Kiro trusted commands.
 41→const trustedCommandsKey = "kiroAgent.trustedCommands"
 42→
 43→// prodTrustedCommand is the trusted command pattern for production installs.
 44→const prodTrustedCommand = "entire hooks *"
 45→
 46→// localDevCmdPrefix is the command prefix used for local development builds.
 47→const localDevCmdPrefix = "go run ${KIRO_PROJECT_DIR}/cmd/entire/main.go "
 48→
 49→// prodHookCmdPrefix is the command prefix for production hook commands.
 50→const prodHookCmdPrefix = "entire hooks kiro "
 51→
 52→// entireHookPrefixes identify Entire hooks in the config file.
 53→var entireHookPrefixes = []string{
 54→	"entire ",
 55→	localDevCmdPrefix,
 56→}
 57→
 58→// ideHookDef defines a single IDE hook file to install.
 59→type ideHookDef struct {
 60→	Filename    string // e.g. "entire-prompt-submit"
 61→	TriggerType string // e.g. "promptSubmit"
 62→	CLIVerb     string // e.g. "user-prompt-submit"
 63→}
 64→
 65→// ideHookDefs lists the 4 IDE hook files to install.
 66→// No agentSpawn IDE hook — the IDE has no such trigger.
 67→// The first promptSubmit serves as session start.
 68→var ideHookDefs = []ideHookDef{
 69→	{Filename: "entire-prompt-submit", TriggerType: "promptSubmit", CLIVerb: HookNameUserPromptSubmit},
 70→	{Filename: "entire-stop", TriggerType: "agentStop", CLIVerb: HookNameStop},
 71→	{Filename: "entire-pre-tool-use", TriggerType: "preToolUse", CLIVerb: HookNamePreToolUse},
 72→	{Filename: "entire-post-tool-use", TriggerType: "postToolUse", CLIVerb: HookNamePostToolUse},
 73→}
 74→
 75→// InstallHooks installs Entire hooks in .kiro/agents/entire.json (CLI hooks)
 76→// and .kiro/hooks/*.kiro.hook (IDE hooks).
 77→// Returns the total number of hooks installed (CLI + IDE).
 78→func (k *KiroAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
 79→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 80→	if err != nil {
 81→		worktreeRoot = "."
 82→	}
 83→
 84→	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
 85→
 86→	// If hooks are already installed and not forcing, check if they're current
 87→	if !force {
 88→		if existing, readErr := os.ReadFile(hooksPath); readErr == nil { //nolint:gosec // path constructed from repo root
 89→			var file kiroAgentFile
 90→			if json.Unmarshal(existing, &file) == nil &&
 91→				allHooksPresent(file.Hooks, localDev) &&
 92→				allIDEHooksPresent(worktreeRoot, localDev) &&
 93→				trustedCommandsPresent(worktreeRoot, localDev) {
 94→				return 0, nil
 95→			}
 96→		}
 97→	}
 98→
 99→	cmdPrefix := hookCmdPrefix(localDev)
100→
101→	file := kiroAgentFile{
102→		Name: "entire",
103→		// Include all default Kiro tools so the agent profile doesn't restrict them.
104→		Tools: []string{
105→			"read", "write", "shell", "grep", "glob",
106→			"aws", "report", "introspect", "knowledge",
107→			"thinking", "todo", "delegate",
108→		},
109→		Hooks: kiroHooks{
110→			AgentSpawn:       []kiroHookEntry{{Command: cmdPrefix + HookNameAgentSpawn}},
111→			UserPromptSubmit: []kiroHookEntry{{Command: cmdPrefix + HookNameUserPromptSubmit}},
112→			PreToolUse:       []kiroHookEntry{{Command: cmdPrefix + HookNamePreToolUse}},
113→			PostToolUse:      []kiroHookEntry{{Command: cmdPrefix + HookNamePostToolUse}},
114→			Stop:             []kiroHookEntry{{Command: cmdPrefix + HookNameStop}},
115→		},
116→	}
117→
118→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
119→		return 0, fmt.Errorf("failed to create .kiro/agents directory: %w", err)
120→	}
121→
122→	output, err := jsonutil.MarshalIndentWithNewline(file, "", "  ")
123→	if err != nil {
124→		return 0, fmt.Errorf("failed to marshal hooks config: %w", err)
125→	}
126→
127→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
128→		return 0, fmt.Errorf("failed to write hooks config: %w", err)
129→	}
130→
131→	// Install IDE hooks (.kiro/hooks/*.kiro.hook)
132→	ideCount, err := installIDEHooks(worktreeRoot, cmdPrefix)
133→	if err != nil {
134→		return 0, fmt.Errorf("failed to install IDE hooks: %w", err)
135→	}
136→
137→	// Configure trusted commands in .vscode/settings.json
138→	if err := installTrustedCommands(worktreeRoot, localDev); err != nil {
139→		return 0, fmt.Errorf("failed to configure trusted commands: %w", err)
140→	}
141→
142→	return len(k.HookNames()) + ideCount, nil
143→}
144→
145→// UninstallHooks removes the Entire hooks config file and IDE hook files.
146→func (k *KiroAgent) UninstallHooks(ctx context.Context) error {
147→	worktreeRoot, err := paths.WorktreeRoot(ctx)
148→	if err != nil {
149→		worktreeRoot = "."
150→	}
151→
152→	// Remove CLI agent file
153→	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
154→	if err := os.Remove(hooksPath); err != nil && !os.IsNotExist(err) {
155→		return fmt.Errorf("failed to remove hooks config: %w", err)
156→	}
157→
158→	// Remove IDE hook files
159→	for _, def := range ideHookDefs {
160→		idePath := filepath.Join(worktreeRoot, ".kiro", ideHooksDir, def.Filename+ideHookFileSuffix)
161→		if err := os.Remove(idePath); err != nil && !os.IsNotExist(err) {
162→			return fmt.Errorf("failed to remove IDE hook %s: %w", def.Filename, err)
163→		}
164→	}
165→
166→	// Remove trusted commands from .vscode/settings.json
167→	if err := uninstallTrustedCommands(worktreeRoot); err != nil {
168→		return fmt.Errorf("failed to remove trusted commands: %w", err)
169→	}
170→
171→	return nil
172→}
173→
174→// AreHooksInstalled checks if Entire hooks are installed.
175→// Returns true if EITHER CLI agent hooks or IDE hooks are present.
176→func (k *KiroAgent) AreHooksInstalled(ctx context.Context) bool {
177→	worktreeRoot, err := paths.WorktreeRoot(ctx)
178→	if err != nil {
179→		worktreeRoot = "."
180→	}
181→
182→	// Check CLI agent hooks
183→	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
184→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
185→	if err == nil {
186→		var file kiroAgentFile
187→		if json.Unmarshal(data, &file) == nil {
188→			if hasEntireHook(file.Hooks.AgentSpawn) ||
189→				hasEntireHook(file.Hooks.UserPromptSubmit) ||
190→				hasEntireHook(file.Hooks.Stop) {
191→				return true
192→			}
193→		}
194→	}
195→
196→	// Check IDE hooks — any Entire IDE hook file means hooks are installed
197→	return anyIDEHookPresent(worktreeRoot)
198→}
199→
200→// GetSupportedHooks returns the hook types Kiro supports.
201→func (k *KiroAgent) GetSupportedHooks() []agent.HookType {
202→	return []agent.HookType{
203→		agent.HookSessionStart,
204→		agent.HookUserPromptSubmit,
205→		agent.HookPreToolUse,
206→		agent.HookPostToolUse,
207→		agent.HookStop,
208→	}
209→}
210→
211→func allHooksPresent(hooks kiroHooks, localDev bool) bool {
212→	cmdPrefix := hookCmdPrefix(localDev)
213→
214→	return hookCommandExists(hooks.AgentSpawn, cmdPrefix+HookNameAgentSpawn) &&
215→		hookCommandExists(hooks.UserPromptSubmit, cmdPrefix+HookNameUserPromptSubmit) &&
216→		hookCommandExists(hooks.PreToolUse, cmdPrefix+HookNamePreToolUse) &&
217→		hookCommandExists(hooks.PostToolUse, cmdPrefix+HookNamePostToolUse) &&
218→		hookCommandExists(hooks.Stop, cmdPrefix+HookNameStop)
219→}
220→
221→func hookCommandExists(entries []kiroHookEntry, command string) bool {
222→	for _, entry := range entries {
223→		if entry.Command == command {
224→			return true
225→		}
226→	}
227→	return false
228→}
229→
230→func isEntireHook(command string) bool {
231→	for _, prefix := range entireHookPrefixes {
232→		if strings.HasPrefix(command, prefix) {
233→			return true
234→		}
235→	}
236→	return false
237→}
238→
239→func hasEntireHook(entries []kiroHookEntry) bool {
240→	for _, entry := range entries {
241→		if isEntireHook(entry.Command) {
242→			return true
243→		}
244→	}
245→	return false
246→}
247→
248→func hookCmdPrefix(localDev bool) string {
249→	if localDev {
250→		return localDevCmdPrefix + "hooks kiro "
251→	}
252→	return prodHookCmdPrefix
253→}
254→
255→// installIDEHooks creates .kiro/hooks/*.kiro.hook files for the Kiro IDE.
256→func installIDEHooks(worktreeRoot, cmdPrefix string) (int, error) {
257→	dir := filepath.Join(worktreeRoot, ".kiro", ideHooksDir)
258→	if err := os.MkdirAll(dir, 0o750); err != nil {
259→		return 0, fmt.Errorf("failed to create .kiro/hooks directory: %w", err)
260→	}
261→
262→	for _, def := range ideHookDefs {
263→		hook := kiroIDEHookFile{
264→			Enabled:     true,
265→			Name:        def.Filename,
266→			Description: "Entire CLI " + def.TriggerType + " hook",
267→			Version:     ideHookVersion,
268→			When: kiroIDEHookWhen{
269→				Type: def.TriggerType,
270→			},
271→			Then: kiroIDEHookThen{
272→				Type:    "runCommand",
273→				Command: cmdPrefix + def.CLIVerb,
274→			},
275→		}
276→
277→		data, err := jsonutil.MarshalIndentWithNewline(hook, "", "  ")
278→		if err != nil {
279→			return 0, fmt.Errorf("failed to marshal IDE hook %s: %w", def.Filename, err)
280→		}
281→
282→		path := filepath.Join(dir, def.Filename+ideHookFileSuffix)
283→		if err := os.WriteFile(path, data, 0o600); err != nil {
284→			return 0, fmt.Errorf("failed to write IDE hook %s: %w", def.Filename, err)
285→		}
286→	}
287→
288→	return len(ideHookDefs), nil
289→}
290→
291→// allIDEHooksPresent checks that all 4 IDE hook files exist and have correct commands.
292→func allIDEHooksPresent(worktreeRoot string, localDev bool) bool {
293→	cmdPrefix := hookCmdPrefix(localDev)
294→
295→	for _, def := range ideHookDefs {
296→		path := filepath.Join(worktreeRoot, ".kiro", ideHooksDir, def.Filename+ideHookFileSuffix)
297→		data, err := os.ReadFile(path) //nolint:gosec // path constructed from repo root
298→		if err != nil {
299→			return false
300→		}
301→		var hook kiroIDEHookFile
302→		if err := json.Unmarshal(data, &hook); err != nil {
303→			return false
304→		}
305→		if hook.Then.Command != cmdPrefix+def.CLIVerb {
306→			return false
307→		}
308→	}
309→	return true
310→}
311→
312→// anyIDEHookPresent checks if any Entire IDE hook file exists.
313→func anyIDEHookPresent(worktreeRoot string) bool {
314→	for _, def := range ideHookDefs {
315→		path := filepath.Join(worktreeRoot, ".kiro", ideHooksDir, def.Filename+ideHookFileSuffix)
316→		data, err := os.ReadFile(path) //nolint:gosec // path constructed from repo root
317→		if err != nil {
318→			continue
319→		}
320→		var hook kiroIDEHookFile
321→		if json.Unmarshal(data, &hook) == nil && isEntireIDEHook(hook) {
322→			return true
323→		}
324→	}
325→	return false
326→}
327→
328→// isEntireIDEHook checks if an IDE hook file belongs to Entire.
329→func isEntireIDEHook(hook kiroIDEHookFile) bool {
330→	return strings.HasPrefix(hook.Name, "entire-") && isEntireHook(hook.Then.Command)
331→}
332→
333→// trustedCommand returns the trusted command pattern for the given mode.
334→func trustedCommand(localDev bool) string {
335→	if localDev {
336→		return localDevCmdPrefix + "hooks *"
337→	}
338→	return prodTrustedCommand
339→}
340→
341→// isEntireTrustedCommand checks if a command string is an Entire trusted command.
342→func isEntireTrustedCommand(cmd string) bool {
343→	return cmd == prodTrustedCommand || cmd == localDevCmdPrefix+"hooks *"
344→}
