// Compile-time interface assertions.
var (
	_ agent.TranscriptAnalyzer = (*KiroAgent)(nil)
	_ agent.HookResponseWriter = (*KiroAgent)(nil)
)

// WriteHookResponse outputs the hook response as plain text to stdout.
// Kiro IDE does not parse JSON hook responses (unlike Claude Code),
// so we write plain text that the IDE reads as command output.
// Even an empty message produces a newline, which is enough to prevent
// the IDE's runCommand executor from timing out.
func (k *KiroAgent) WriteHookResponse(message string) error {
	if _, err := fmt.Fprintln(os.Stdout, message); err != nil {
		return fmt.Errorf("failed to write hook response: %w", err)
	}
	return nil
}

