func TestWriteHookResponse(t *testing.T) {
	t.Parallel()

	ag := &KiroAgent{}

	// Capture stdout by redirecting os.Stdout to a pipe.
	oldStdout := os.Stdout
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("failed to create pipe: %v", err)
	}
	os.Stdout = w

	writeErr := ag.WriteHookResponse("hello from kiro")

	// Restore stdout and read captured output.
	os.Stdout = oldStdout
	w.Close()
	captured, readErr := os.ReadFile(r.Name())
	// os.ReadFile won't work on a pipe; use a different approach.
	_ = captured
	_ = readErr

	// Read from the pipe directly.
	buf := make([]byte, 256)
	n, _ := r.Read(buf)
	r.Close()
	output := string(buf[:n])

	if writeErr != nil {
		t.Fatalf("WriteHookResponse() error = %v", writeErr)
	}
	if output != "hello from kiro\n" {
		t.Errorf("WriteHookResponse() output = %q, want %q", output, "hello from kiro\n")
	}
}

